-- Table: inventory_stock_balance
-- Source: accounting_admin_db.sql (5. Inventory)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS inventory_stock_balance (
    product_id       BIGINT NOT NULL REFERENCES masterdata_product(id),
    warehouse_id     BIGINT NOT NULL REFERENCES masterdata_warehouse(id),
    quantity_on_hand NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (quantity_on_hand >= 0),
    quantity_reserved NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (quantity_reserved >= 0),
    average_cost     NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (average_cost >= 0),
    last_movement_at TIMESTAMPTZ,
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (product_id, warehouse_id)
);
